"""Original 32 px engineering icon geometry. No vendor artwork is included."""
from html import escape

def p(d, **attrs):
    return '<path d="'+d+'"'+''.join(f' {k.replace("_", "-")}="{v}"' for k,v in attrs.items())+'/>'
def r(x,y,w,h,rx=2, **attrs):
    return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{rx}"'+''.join(f' {k.replace("_", "-")}="{v}"' for k,v in attrs.items())+'/>'
def c(x,y,rad,**attrs):
    return f'<circle cx="{x}" cy="{y}" r="{rad}"'+''.join(f' {k.replace("_", "-")}="{v}"' for k,v in attrs.items())+'/>'
def g(content,**attrs):
    return '<g'+''.join(f' {k.replace("_", "-")}="{v}"' for k,v in attrs.items())+'>'+content+'</g>'
TEAL='#178b88'; PALE='#d7efed'; INK='#253b53'; AMBER='#c88626'
def accent(d,**attrs):return p(d,stroke=TEAL,**attrs)
def fill(d):return p(d,fill=PALE)
def cube(x=6,y=5,w=18,h=20):
    return fill(f'M {x} {y+5} {x+w/2} {y} {x+w} {y+5} v {h-5} l {-w/2} 5 {-w/2} -5 Z')+p(f'M {x} {y+5} l {w/2} 5 {w/2} -5 M {x+w/2} {y+10} v {h-5}')
def nodes(points):return ''.join(c(x,y,1.5,fill='white') for x,y in points)

def record(id,en,ja,body,tags=''):
    return dict(id=id,name=en,nameJa=ja,body=body,tags=tags.split(','))
CORE={}
def add(domain,id,en,ja,body,tags=''):
    CORE.setdefault(domain,[]).append(record(id,en,ja,body,tags))
